'=>'曲目数','remark'=>'备注','writers'=>'编剧','keywords'=>'关键词','release_dates'=>'上映信息',];public static function schema(){return['types'=>self::TYPES,'labels'=>self::LABELS,'extra_fields'=>self::EXTRA_FIELDS,'extra_labels'=>self::EXTRA_LABELS,];}public static function label($a){return(isset(self::LABELS[$a])?self::LABELS[$a]:$a);}public static function cleanPersonName($a){$a=(string)$a;if($a!==''&&!preg_match('//u',$a)){return'';}foreach(array('/[\x{200B}-\x{200D}\x{FEFF}\x{2060}]+/u'=>'','/[\x{00A0}\x{1680}\x{2000}-\x{200A}\x{3000}]+/u'=>' ',)as $b=>$c){$d=preg_replace($b,$c,$a);if(is_string($d)){$a=$d;}}$a=trim($a);if($a===''){return'';}if(preg_match('/^[\p{P}\p{S}\p{Z}\s]+$/u',$a)){return'';}$e=strtolower($a);if(in_array($e,array('n/a','na','none','null','tbd','未知','不详','暂无','暂缺'),true)){return'';}return $a;}}